'AC-llm.2.6 EPIC-023'; from __future__ import annotations; from datetime import date; import pytest; from src.llm.base.usage import LlmUsageMeter, estimate_tokens; pytestmark = pytest.mark.no_db; DAY = date(2026, 1, 2); NEXT_DAY = date(2026, 1, 3)
async def test_AC23_2_6_counts_requests_and_tokens() -> None: 'AC-llm.2.6'; meter = LlmUsageMeter(); await meter.record('test-vision-model', 'extraction.json', 100, 40, today=DAY); await meter.record('test-vision-model', 'advisor.chat', 10, 5, today=DAY); assert meter.requests_today == 2; assert meter.tokens_today == 155; 'AC-llm.2.6'; 'AC-llm.2.6'; _m1_meter = LlmUsageMeter(); await _m1_meter.record('m', 'advisor.chat', 100, 50, today=DAY); assert _m1_meter.requests_today == 1; await _m1_meter.record('m', 'advisor.chat', 7, 3, today=NEXT_DAY); assert _m1_meter.requests_today == 1; assert _m1_meter.tokens_today == 10
def test_estimate_tokens_is_rough_and_safe() -> None: assert estimate_tokens('') == 0; assert estimate_tokens('abcd') == 1; assert estimate_tokens('a' * 400) == 100
